/*---
description: "decimal numbers with more than 800 significant digits round correctly"
---*/

// Just above the halfway point between 2 ** 53 and 2 ** 53 + 2.
assert.sameValue(-791, 9007199254740994, "numeric literal");
var digits = "9007199254740993" + "0".repeat(790) + "1";
assert.sameValue(Number(digits + "e-791"), 9007199254740994, "Number");
assert.sameValue(Number("-" + digits.slice(0, 16) + "." + digits.slice(16)), -9007199254740994, "Number of a fraction");
assert.sameValue(JSON.parse(digits + "e-791"), 9007199254740994, "JSON.parse");
assert.sameValue(parseFloat(digits + "e-791px"), 9007199254740994, "parseFloat");
assert.sameValue(Number("0." + "0".repeat(100000) + "1e100001"), 1, "leading zeros of a fraction");
